// 定义品牌类型
type Currency<T> = number & { __currency: T };
type USD = Currency<"usd">;
type EUR = Currency<"euro">;
type CNY = Currency<"cny">;

interface Product {
  price: USD;
  name: string;
}

// 使用
const productPrice = 100 as USD;
const euroPrice = 85 as EUR;

const product: Product = {
  price: productPrice,  // ✅ 正常
  name: "iPhone"
};

// ❌ 错误：不能把欧元价格赋值给美元字段
const wrongProduct: Product = {
  price: euroPrice,  // Type 'EUR' is not assignable to type 'USD'
  name: "iPhone"
};

type Guid<T> = string & { __guid: T };

type UserId = Guid<"user">;
type OrderId = Guid<"order">;
type ProductId = Guid<"product">;

interface User {
  id: UserId;
  name: string;
}

interface Order {
  id: OrderId;
  userId: UserId;
  total: number;
}

declare function getUserById(id: UserId): Promise<User>;
declare function getOrderById(id: OrderId): Promise<Order>;

// 使用
async function processOrder(orderId: OrderId) {
  const order = await getOrderById(orderId);

  // ❌ 编译错误：不能把 OrderId 传给需要 UserId 的函数
  const wrongUser = await getUserById(orderId);

  // ✅ 正确：使用 order.userId
  const user = await getUserById(order.userId);
}

type SafeString = string & { __sanitized: true };

// 必须经过清洗函数才能使用
function sanitize(input: string): SafeString {
  // 移除 <script> 等危险标签
  return input.replace(/<script.*?>.*?<\/script>/gi, '') as SafeString;
}

function renderToPage(html: SafeString) {
  document.body.innerHTML += html;
}

const userInput = `<script>alert('hack')</script>Hello`;

// ❌ 错误：不能直接渲染未清洗的输入
renderToPage(userInput);

// ✅ 正确：先清洗再渲染
renderToPage(sanitize(userInput));
